const store = $getWorkflowStaticData('global');

// Seed default admin user on first run
if (!store.users || store.users.length === 0) {
  store.users = [{
    id: 'U001',
    email: 'admin@company.com',
    password: 'admin123',
    name: 'Admin User',
    role: 'admin',
    companyName: 'My Company'
  }];
}

const body = $input.first().json.body;
const { email, password } = body.data || {};

if (!email || !password) {
  return [{ json: { success: false, message: 'Email and password are required.' } }];
}

const user = store.users.find(u => u.email.toLowerCase() === email.toLowerCase() && u.password === password);

if (!user) {
  return [{ json: { success: false, message: 'Invalid email or password.' } }];
}

const token = 'sess_' + Date.now() + '_' + Math.random().toString(36).slice(2, 10);

return [{ json: {
  success: true,
  message: 'Login successful',
  data: {
    token,
    userId: user.id,
    name: user.name,
    email: user.email,
    role: user.role,
    companyName: user.companyName || 'My Company',
    expiresAt: Date.now() + 8 * 60 * 60 * 1000
  }
}}];

const store = $getWorkflowStaticData('global');
if (!store.employees) store.employees = [];

const emp = $input.first().json.body.data;
if (!emp || !emp.employeeId) {
  return [{ json: { success: false, message: 'Missing employee data.' } }];
}

const idx = store.employees.findIndex(e => e.employeeId === emp.employeeId);
if (idx >= 0) {
  store.employees[idx] = emp;
} else {
  store.employees.push(emp);
}

return [{ json: { success: true, data: emp, message: idx >= 0 ? 'Employee updated.' : 'Employee created.' } }];

const store = $getWorkflowStaticData('global');
if (!store.employees) store.employees = [];

const { employeeId } = $input.first().json.body.data || {};
if (!employeeId) return [{ json: { success: false, message: 'Missing employeeId.' } }];

store.employees = store.employees.filter(e => e.employeeId !== employeeId);
if (store.attendance) store.attendance = store.attendance.filter(a => a.employeeId !== employeeId);
if (store.leaves) store.leaves = store.leaves.filter(l => l.employeeId !== employeeId);

return [{ json: { success: true, message: 'Employee deleted.' } }];

const store = $getWorkflowStaticData('global');
if (!store.attendance) store.attendance = [];

const rec = $input.first().json.body.data;
if (!rec || !rec.id) return [{ json: { success: false, message: 'Missing attendance data.' } }];

const idx = store.attendance.findIndex(a => a.id === rec.id);
if (idx >= 0) {
  store.attendance[idx] = rec;
} else {
  store.attendance.push(rec);
}

return [{ json: { success: true, data: rec, message: 'Attendance saved.' } }];

const store = $getWorkflowStaticData('global');
const { month } = $input.first().json.body.data || {};
const records = store.attendance || [];
const filtered = month ? records.filter(r => r.date && r.date.startsWith(month)) : records;
return [{ json: { success: true, data: filtered } }];

const store = $getWorkflowStaticData('global');
if (!store.attendance) store.attendance = [];

const { id } = $input.first().json.body.data || {};
if (!id) return [{ json: { success: false, message: 'Missing id.' } }];

const before = store.attendance.length;
store.attendance = store.attendance.filter(a => a.id !== id);
const deleted = before - store.attendance.length;

return [{ json: { success: true, message: deleted > 0 ? 'Record deleted.' : 'Record not found.' } }];

const store = $getWorkflowStaticData('global');
if (!store.payrolls) store.payrolls = [];

const body = $input.first().json.body;
const { month, payrolls: incoming } = body.data || {};

if (!month || !incoming) return [{ json: { success: false, message: 'Missing month or payroll data.' } }];

store.payrolls = store.payrolls.filter(p => p.month !== month);
store.payrolls.push(...incoming);

return [{ json: { success: true, data: incoming, message: 'Payroll saved for ' + month + '.' } }];

const store = $getWorkflowStaticData('global');
const { month } = $input.first().json.body.data || {};
const records = store.payrolls || [];
const filtered = month ? records.filter(p => p.month === month) : records;
return [{ json: { success: true, data: filtered } }];

const store = $getWorkflowStaticData('global');
if (!store.leaves) store.leaves = [];

const leave = $input.first().json.body.data;
if (!leave || !leave.id || !leave.employeeId) {
  return [{ json: { success: false, message: 'Missing leave data.' } }];
}

// Prevent duplicate submissions
const existing = store.leaves.findIndex(l => l.id === leave.id);
if (existing >= 0) {
  store.leaves[existing] = leave;
} else {
  leave.status = leave.status || 'Pending';
  leave.appliedOn = leave.appliedOn || new Date().toISOString().slice(0, 10);
  store.leaves.unshift(leave);
}

return [{ json: { success: true, data: leave, message: 'Leave request submitted.' } }];

const store = $getWorkflowStaticData('global');
if (!store.leaves) store.leaves = [];

const { id, approvedBy, approvedOn } = $input.first().json.body.data || {};
if (!id) return [{ json: { success: false, message: 'Missing leave id.' } }];

const leave = store.leaves.find(l => l.id === id);
if (!leave) return [{ json: { success: false, message: 'Leave not found.' } }];

leave.status = 'Approved';
leave.approvedBy = approvedBy || 'Admin';
leave.approvedOn = approvedOn || new Date().toISOString().slice(0, 10);

return [{ json: { success: true, data: leave, message: 'Leave approved.' } }];

const store = $getWorkflowStaticData('global');
if (!store.leaves) store.leaves = [];

const { id, rejectedBy, rejectedOn, reason } = $input.first().json.body.data || {};
if (!id) return [{ json: { success: false, message: 'Missing leave id.' } }];

const leave = store.leaves.find(l => l.id === id);
if (!leave) return [{ json: { success: false, message: 'Leave not found.' } }];

leave.status = 'Rejected';
leave.rejectedBy = rejectedBy || 'Admin';
leave.rejectedOn = rejectedOn || new Date().toISOString().slice(0, 10);
if (reason) leave.rejectionReason = reason;

return [{ json: { success: true, data: leave, message: 'Leave rejected.' } }];

const store = $getWorkflowStaticData('global');
const { employeeId, status, year } = $input.first().json.body.data || {};
let leaves = store.leaves || [];
if (employeeId) leaves = leaves.filter(l => l.employeeId === employeeId);
if (status) leaves = leaves.filter(l => l.status === status);
if (year) leaves = leaves.filter(l => l.fromDate && l.fromDate.startsWith(String(year)));
return [{ json: { success: true, data: leaves, total: leaves.length } }];

const store = $getWorkflowStaticData('global');

// Seed India 2025 holidays on first run
if (!store.holidays || store.holidays.length === 0) {
  store.holidays = [
    { id:'H001', name:"New Year's Day",    date:'2025-01-01', type:'National', isPaid:true,  desc:'' },
    { id:'H002', name:'Republic Day',      date:'2025-01-26', type:'National', isPaid:true,  desc:'National holiday' },
    { id:'H003', name:'Holi',              date:'2025-03-14', type:'National', isPaid:true,  desc:'' },
    { id:'H004', name:'Eid ul-Fitr',       date:'2025-03-31', type:'National', isPaid:true,  desc:'' },
    { id:'H005', name:'Ambedkar Jayanti',  date:'2025-04-14', type:'National', isPaid:true,  desc:'' },
    { id:'H006', name:'Good Friday',       date:'2025-04-18', type:'National', isPaid:true,  desc:'' },
    { id:'H007', name:'Labour Day',        date:'2025-05-01', type:'National', isPaid:true,  desc:'International Workers Day' },
    { id:'H008', name:'Independence Day',  date:'2025-08-15', type:'National', isPaid:true,  desc:'National holiday' },
    { id:'H009', name:'Gandhi Jayanti',    date:'2025-10-02', type:'National', isPaid:true,  desc:'National holiday' },
    { id:'H010', name:'Diwali',            date:'2025-10-20', type:'National', isPaid:true,  desc:'' },
    { id:'H011', name:'Christmas Day',     date:'2025-12-25', type:'National', isPaid:true,  desc:'' }
  ];
}

const { year } = $input.first().json.body.data || {};
let holidays = store.holidays;
if (year) holidays = holidays.filter(h => h.date.startsWith(String(year)));
holidays = holidays.sort((a, b) => a.date.localeCompare(b.date));

return [{ json: { success: true, data: holidays, total: holidays.length } }];

const store = $getWorkflowStaticData('global');
if (!store.holidays) store.holidays = [];

const h = $input.first().json.body.data;
if (!h || !h.name || !h.date) {
  return [{ json: { success: false, message: 'Missing holiday name or date.' } }];
}

if (!h.id) h.id = 'H' + Date.now();

const idx = store.holidays.findIndex(x => x.id === h.id);
if (idx >= 0) {
  store.holidays[idx] = h;
} else {
  store.holidays.push(h);
}

return [{ json: { success: true, data: h, message: idx >= 0 ? 'Holiday updated.' : 'Holiday added.' } }];

const store = $getWorkflowStaticData('global');
if (!store.holidays) store.holidays = [];

const { id } = $input.first().json.body.data || {};
if (!id) return [{ json: { success: false, message: 'Missing holiday id.' } }];

const before = store.holidays.length;
store.holidays = store.holidays.filter(h => h.id !== id);
const deleted = before - store.holidays.length;

return [{ json: { success: true, message: deleted > 0 ? 'Holiday deleted.' : 'Holiday not found.' } }];

const store = $getWorkflowStaticData('global');
if (!store.bioLog) store.bioLog = [];

const { employeeId, deviceUserId, date, time } = $input.first().json.body.data || {};
if (!employeeId) return [{ json: { success: false, message: 'Missing employeeId.' } }];

// Find the employee
const employees = store.employees || [];
const emp = employees.find(e => e.employeeId === employeeId);
if (!emp) return [{ json: { success: false, message: 'Employee not found.' } }];

// Prevent duplicate attendance for same day
if (!store.attendance) store.attendance = [];
const todayDate = date || new Date().toISOString().slice(0, 10);
const existing = store.attendance.find(a => a.employeeId === employeeId && a.date === todayDate);
if (!existing) {
  store.attendance.push({
    id: 'bio_' + Date.now(),
    employeeId,
    date: todayDate,
    status: 'Present',
    hoursWorked: 8,
    overtimeHours: 0,
    lateMinutes: 0,
    remarks: 'Biometric'
  });
}

// Append to bio log
store.bioLog.unshift({
  id: 'bl_' + Date.now(),
  employeeId,
  deviceUserId: deviceUserId || emp.biometricDeviceId,
  date: todayDate,
  time: time || new Date().toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit', hour12: true }),
  status: 'Present',
  timestamp: new Date().toISOString()
});
// Keep only last 500 log entries
if (store.bioLog.length > 500) store.bioLog = store.bioLog.slice(0, 500);

return [{ json: { success: true, data: { employeeName: emp.employeeName, employeeId, date: todayDate }, message: 'Attendance marked via biometric.' } }];

const store = $getWorkflowStaticData('global');
if (!store.employees) store.employees = [];

const { employeeId, deviceUserId } = $input.first().json.body.data || {};
if (!employeeId || !deviceUserId) {
  return [{ json: { success: false, message: 'Missing employeeId or deviceUserId.' } }];
}

// Check for duplicate device user ID
const duplicate = store.employees.find(e => e.biometricDeviceId === deviceUserId && e.employeeId !== employeeId);
if (duplicate) {
  return [{ json: { success: false, message: 'Device user ID ' + deviceUserId + ' is already assigned to ' + duplicate.employeeName + '.' } }];
}

const emp = store.employees.find(e => e.employeeId === employeeId);
if (!emp) return [{ json: { success: false, message: 'Employee not found.' } }];

emp.biometricDeviceId = deviceUserId;
return [{ json: { success: true, data: { employeeId, deviceUserId, employeeName: emp.employeeName }, message: emp.employeeName + ' enrolled with device ID: ' + deviceUserId } }];
